sprites.onOverlap(SpriteKind.río, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("El guacamayo de Spix (Cyanopsitta spixii), también conocido como guacamayo azul pequeño, es un ave psitaciforme endémica de Brasil y se hizo mundialmente famoso por inspirar la película animada Río", DialogLayout.Bottom)
    game.showLongText("Tamaño y peso: Mide entre 55 y 60 cm de longitud. Los machos pesan alrededor de 320 g y las hembras cerca de 290 g.", DialogLayout.Bottom)
    info.changeScoreBy(10)
    sprites.destroy(guacamayo_de_spix, effects.blizzard, 500)
})
sprites.onOverlap(SpriteKind.rosa, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("El delfín rosado (conocido también como boto, bufeo o tonina) es el delfín de río más grande del mundo", DialogLayout.Bottom)
    game.showLongText("Tamaño y peso: Los adultos miden entre 1,5 y 2,5 metros de longitud y pueden pesar hasta cerca de 185–200 kg. Los machos suelen ser más grandes y rosados que las hembras", DialogLayout.Bottom)
    info.changeScoreBy(10)
    sprites.destroy(Delfin_rosado, effects.blizzard, 500)
})
