sprites.onOverlap(SpriteKind.coin3, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("La piraña roja (Pygocentrus nattereri), también conocida como piraña de vientre rojo, es un pez carnívoro de agua dulce originario de Sudamérica (cuencas del Amazonas, Orinoco y Paraná-Paraguay)", DialogLayout.Bottom)
    game.showLongText("Tamaño y peso: Alcanzan entre 28 y 38 cm de longitud y un peso de hasta 3,5 kg (pudiendo llegar excepcionalmente a más en condiciones óptimas)", DialogLayout.Bottom)
    info.changeScoreBy(10)
    sprites.destroy(Piraña_roja, effects.blizzard, 500)
})
sprites.onOverlap(SpriteKind.npc, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("Investiga también el río", DialogLayout.Bottom)
    sprites.destroy(Letrero, effects.blizzard, 500)
})
sprites.onOverlap(SpriteKind.pez, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("El candirú (Vandellia cirrhosa), también conocido como pez vampiro o cañero, es un pequeño pez gato de agua dulce de la familia Trichomycteridae, nativo de la cuenca del río Amazonas", DialogLayout.Bottom)
    game.showLongText("Tamaño y peso: Alcanzan entre 28 y 38 cm de longitud y un peso de hasta 3,5 kg (pudiendo llegar excepcionalmente a más en condiciones óptimas)", DialogLayout.Bottom)
    info.changeScoreBy(10)
    sprites.destroy(pez_vampiro, effects.blizzard, 500)
})
sprites.onOverlap(SpriteKind.serpiente, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("La anaconda verde (Eunectes murinus y la recientemente distinguida del norte Eunectes akayima) es la serpiente más pesada y una de las más grandes del mundo, endémica de los ríos y humedales de Sudamérica", DialogLayout.Bottom)
    game.showLongText("Tamaño y peso: Es una especie de gran envergadura donde las hembras son mucho más grandes que los machos. Pueden superar los 6 a 8 metros de longitud y pesar más de 200 a 250 kilogramos.", DialogLayout.Bottom)
    info.changeScoreBy(10)
    sprites.destroy(serpiente, effects.blizzard, 500)
})
sprites.onOverlap(SpriteKind.santi, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("perezoso (suborden Folivora) es un mamífero placentario neotropical famoso por su metabolismo ultralento y su vida casi permanentemente suspendida en los árboles.", DialogLayout.Bottom)
    game.showLongText("Perezoso de tres dedos: Mide aproximadamente entre 50 y 60 centímetros de largo", DialogLayout.Bottom)
    info.changeScoreBy(10)
    sprites.destroy(perezoso, effects.blizzard, 500)
})
sprites.onOverlap(SpriteKind.mono, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("El Alouatta seniculus (conocido comúnmente como mono aullador rojo, aullador colorado o mono congo) es un primate del Nuevo Mundo de la familia Atelidae", DialogLayout.Bottom)
    game.showLongText("Tamaño y peso: Los machos miden entre 49 y 72 cm y pesan cerca de 7,5 kg; las hembras miden de 46 a 57 cm y pesan alrededor de 6,3 kg. Ambos sexos tienen una larga cola prensil de 49 a 75 cm", DialogLayout.Bottom)
    info.changeScoreBy(10)
    sprites.destroy(mono, effects.blizzard, 500)
})
sprites.onOverlap(SpriteKind.rana, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("La rana dorada venenosa (Phyllobates terribilis), también conocida como rana dardo dorada, es considerada uno de los animales más tóxicos del planeta", DialogLayout.Bottom)
    game.showLongText("Tamaño: Mide alrededor de 5 centímetros (las hembras son ligeramente más grandes, hasta 5,5 cm).", DialogLayout.Bottom)
    info.changeScoreBy(10)
    sprites.destroy(rana, effects.blizzard, 500)
})
scene.onOverlapTile(SpriteKind.Player, assets.tile`miMosaico2`, function (sprite, location) {
    if (info.score() >= 90) {
        game.gameOver(true)
    }
})
scene.onOverlapTile(SpriteKind.Player, assets.tile`miMosaico17`, function (sprite, location) {
    tiles.setCurrentTilemap(tilemap`nivel2`)
    tiles.placeOnRandomTile(Rogelio, assets.tile`miMosaico20`)
    tiles.placeOnRandomTile(pez_vampiro, assets.tile`miMosaico21`)
    tiles.placeOnRandomTile(Piraña_roja, assets.tile`miMosaico22`)
    tiles.placeOnRandomTile(Delfin_rosado, assets.tile`miMosaico24`)
})
sprites.onOverlap(SpriteKind.tucan, SpriteKind.Player, function (sprite, otherSprite) {
    game.showLongText("El tucán del Amazonas pertenece a la familia Ramphastidae (que incluye más de 35 a 40 especies en la región neotropical, como el tucán toco y el tucán de garganta blanca). Es uno de los símbolos más representativos de la selva tropical", DialogLayout.Bottom)
    info.changeScoreBy(10)
    sprites.destroy(Tucán, effects.blizzard, 500)
})
